import type { Migration } from './index.ts'

/*
 * Conventions:
 * - IDs are UUID strings generated by the application.
 * - Timestamps are ISO 8601 UTC strings; the application maintains updated_at.
 * - Bars are 1-based, matching how DAWs number them.
 * - vocal_parts is a JSON array of part names; values are validated by the application.
 */
const SECTION_TYPES = `('intro', 'verse', 'pre_chorus', 'chorus', 'bridge', 'instrumental', 'vamp', 'tag', 'interlude', 'ending', 'other')`

export const initialSchema: Migration = {
  version: 1,
  name: 'initial schema',
  sql: `
    -- A song and the musical sections it is built from.
    CREATE TABLE songs (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL CHECK (length(trim(title)) > 0),
      artist TEXT,
      default_key TEXT,
      default_tempo_bpm REAL CHECK (default_tempo_bpm IS NULL OR default_tempo_bpm > 0),
      time_signature_numerator INTEGER NOT NULL DEFAULT 4 CHECK (time_signature_numerator > 0),
      time_signature_denominator INTEGER NOT NULL DEFAULT 4
        CHECK (time_signature_denominator IN (1, 2, 4, 8, 16, 32)),
      notes TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

    CREATE TABLE song_sections (
      id TEXT PRIMARY KEY,
      song_id TEXT NOT NULL REFERENCES songs (id) ON DELETE CASCADE,
      name TEXT NOT NULL CHECK (length(trim(name)) > 0),
      section_type TEXT NOT NULL CHECK (section_type IN ${SECTION_TYPES}),
      length_bars INTEGER NOT NULL CHECK (length_bars > 0),
      vocal_parts TEXT NOT NULL DEFAULT '[]'
        CHECK (json_valid(vocal_parts) AND json_type(vocal_parts) = 'array'),
      instructions TEXT,
      notes TEXT,
      position INTEGER NOT NULL CHECK (position >= 0),
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
    CREATE INDEX song_sections_song ON song_sections (song_id, position);

    -- One song can have many arrangements; each orders and times its sections differently.
    CREATE TABLE arrangements (
      id TEXT PRIMARY KEY,
      song_id TEXT NOT NULL REFERENCES songs (id) ON DELETE CASCADE,
      name TEXT NOT NULL CHECK (length(trim(name)) > 0),
      tempo_bpm REAL CHECK (tempo_bpm IS NULL OR tempo_bpm > 0),
      song_key TEXT,
      notes TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
    CREATE INDEX arrangements_song ON arrangements (song_id);

    -- start_bar..end_bar spans every repeat, and each pass has the same length.
    -- NULL vocal_parts or instructions inherit from the song section.
    CREATE TABLE arrangement_sections (
      id TEXT PRIMARY KEY,
      arrangement_id TEXT NOT NULL REFERENCES arrangements (id) ON DELETE CASCADE,
      song_section_id TEXT NOT NULL REFERENCES song_sections (id) ON DELETE RESTRICT,
      position INTEGER NOT NULL CHECK (position >= 0),
      start_bar INTEGER NOT NULL CHECK (start_bar >= 1),
      end_bar INTEGER NOT NULL CHECK (end_bar >= start_bar),
      repeat_count INTEGER NOT NULL DEFAULT 1 CHECK (repeat_count >= 1),
      vocal_parts TEXT
        CHECK (vocal_parts IS NULL OR (json_valid(vocal_parts) AND json_type(vocal_parts) = 'array')),
      instructions TEXT,
      notes TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      CHECK ((end_bar - start_bar + 1) % repeat_count = 0)
    );
    CREATE INDEX arrangement_sections_arrangement ON arrangement_sections (arrangement_id, position);
    CREATE INDEX arrangement_sections_song_section ON arrangement_sections (song_section_id);

    CREATE TRIGGER arrangement_sections_same_song_insert
    BEFORE INSERT ON arrangement_sections
    WHEN (SELECT song_id FROM song_sections WHERE id = NEW.song_section_id)
      IS NOT (SELECT song_id FROM arrangements WHERE id = NEW.arrangement_id)
    BEGIN
      SELECT RAISE(ABORT, 'arrangement section must belong to the arrangement''s song');
    END;

    CREATE TRIGGER arrangement_sections_same_song_update
    BEFORE UPDATE OF arrangement_id, song_section_id ON arrangement_sections
    WHEN (SELECT song_id FROM song_sections WHERE id = NEW.song_section_id)
      IS NOT (SELECT song_id FROM arrangements WHERE id = NEW.arrangement_id)
    BEGIN
      SELECT RAISE(ABORT, 'arrangement section must belong to the arrangement''s song');
    END;

    -- A setlist is an ordered service plan, such as Sunday morning.
    CREATE TABLE setlists (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL CHECK (length(trim(name)) > 0),
      service_date TEXT CHECK (service_date IS NULL OR date(service_date) = service_date),
      notes TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

    -- One planned or played rendition of a song. Its sections are copied from the
    -- source arrangement so later arrangement edits never rewrite history.
    CREATE TABLE performances (
      id TEXT PRIMARY KEY,
      setlist_id TEXT REFERENCES setlists (id) ON DELETE CASCADE,
      position INTEGER CHECK (position IS NULL OR position >= 0),
      song_id TEXT NOT NULL REFERENCES songs (id) ON DELETE RESTRICT,
      arrangement_id TEXT REFERENCES arrangements (id) ON DELETE SET NULL,
      status TEXT NOT NULL DEFAULT 'planned'
        CHECK (status IN ('planned', 'live', 'completed', 'cancelled')),
      started_at TEXT,
      ended_at TEXT,
      notes TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
    CREATE INDEX performances_setlist ON performances (setlist_id, position);
    CREATE INDEX performances_song ON performances (song_id);
    CREATE INDEX performances_arrangement ON performances (arrangement_id);

    CREATE TABLE performance_sections (
      id TEXT PRIMARY KEY,
      performance_id TEXT NOT NULL REFERENCES performances (id) ON DELETE CASCADE,
      song_section_id TEXT REFERENCES song_sections (id) ON DELETE SET NULL,
      position INTEGER NOT NULL CHECK (position >= 0),
      name TEXT NOT NULL CHECK (length(trim(name)) > 0),
      section_type TEXT NOT NULL CHECK (section_type IN ${SECTION_TYPES}),
      start_bar INTEGER NOT NULL CHECK (start_bar >= 1),
      end_bar INTEGER NOT NULL CHECK (end_bar >= start_bar),
      repeat_count INTEGER NOT NULL DEFAULT 1 CHECK (repeat_count >= 1),
      vocal_parts TEXT NOT NULL DEFAULT '[]'
        CHECK (json_valid(vocal_parts) AND json_type(vocal_parts) = 'array'),
      instructions TEXT,
      notes TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      CHECK ((end_bar - start_bar + 1) % repeat_count = 0)
    );
    CREATE INDEX performance_sections_performance ON performance_sections (performance_id, position);
    CREATE INDEX performance_sections_song_section ON performance_sections (song_section_id);

    -- Machines that have connected to the engine. id is the client's stable clientId.
    CREATE TABLE devices (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      role TEXT NOT NULL CHECK (role IN ('desktop', 'display', 'daw_bridge')),
      last_address TEXT,
      first_seen_at TEXT NOT NULL,
      last_seen_at TEXT NOT NULL
    );

    -- One continuous connection from a DAW bridge.
    CREATE TABLE daw_sessions (
      id TEXT PRIMARY KEY,
      device_id TEXT NOT NULL REFERENCES devices (id) ON DELETE CASCADE,
      daw TEXT NOT NULL CHECK (daw IN ('ableton_live', 'logic_pro', 'simulator')),
      project_name TEXT,
      performance_id TEXT REFERENCES performances (id) ON DELETE SET NULL,
      connected_at TEXT NOT NULL,
      disconnected_at TEXT
    );
    CREATE INDEX daw_sessions_device ON daw_sessions (device_id);
    CREATE INDEX daw_sessions_performance ON daw_sessions (performance_id);

    -- Append-only log of what happened during a performance (transport, overrides, transitions).
    -- source_seq is the sender's sequence number, used to reject stale or duplicate events.
    CREATE TABLE performance_events (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      performance_id TEXT NOT NULL REFERENCES performances (id) ON DELETE CASCADE,
      daw_session_id TEXT REFERENCES daw_sessions (id) ON DELETE SET NULL,
      source TEXT NOT NULL CHECK (source IN ('daw', 'manual', 'system')),
      event_type TEXT NOT NULL,
      source_seq INTEGER,
      payload TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(payload)),
      occurred_at TEXT NOT NULL,
      recorded_at TEXT NOT NULL
    );
    CREATE INDEX performance_events_performance ON performance_events (performance_id, id);
    CREATE INDEX performance_events_daw_session ON performance_events (daw_session_id);
  `,
}
